运行下面的程序，输出是什么？
<pre class='code' data-lang='python'>class Student:
    def __init__(self, name):
        self.name = name
        self._score = 0

    @property
    def score(self):
        return self._score

    @score.setter
    def score(self, value):
        if 0 <= value <= 100:
            self._score = value
        else:
            print('拒绝：分数必须在 0 到 100 之间')

xm = Student('小明')
xm.score = 90
xm.score = 150
print(xm.score)</pre>

