class Volume:
    def __init__(self, level):
        self.volume = level

    @property
    def volume(self):
        return self._level

    @volume.setter
    def volume(self, value):
        if value < 0:
            self._level = 0
        elif value > 10:
            self._level = 10
        else:
            self._level = value

v = Volume(15)
print(v.volume)
v.volume = -5
print(v.volume)
v.volume = 7
print(v.volume)
